import { useEffect, useState, type ReactNode } from 'react';
import {
  Activity, ArrowRight, Bell, Camera, Check, ChevronDown, ClipboardCheck, Clock3, Crosshair,
  FileCheck2, FilePlus2, Filter, Gauge, Home, LogOut, MapPin, Menu, Navigation, Radio, Search,
  Send, Sparkles, Star, Users, X, type LucideIcon,
} from 'lucide-react';
import { analyzeDemo, type AnalysisResult } from '@/lib/demo-ai';
import { domainConfigs, getDomain, legacyDomainMap, type DomainConfig, type DomainKey, type Severity } from '@/lib/domain-config';
import { nextIncidentId, readStoredIncidents, writeStoredIncidents, type Incident, type IncidentStatus } from '@/lib/incident-store';
import { riskForIssue, severityTone } from '@/lib/risk-scoring';
import { recommendTeam, teams, type Team } from '@/lib/team-allocation';

type Role = 'citizen' | 'inspector' | 'admin';
type Page = 'dashboard' | 'complaints' | 'monitor' | 'reports' | 'teams';
const storageKeys = { session: 'inspectiq-session', domain: 'inspectiq-domain', incidents: 'inspectiq-incidents' };
const nowParts = () => { const date = new Date(); return { date: date.toISOString().slice(0, 10), time: date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) }; };
const seedIncidents: Incident[] = [
  { id: 'INC-1024', domain: 'roads-highways', issue: 'Pothole', description: 'A deep pothole is forcing two-wheelers into the traffic lane near the school crossing.', location: 'Alder Avenue & 3rd', date: '2025-06-17', time: '09:42', severity: 'CRITICAL', riskScore: 44, recommendation: 'Place a temporary warning marker and schedule a patch crew before the next commuter peak.', status: 'Inspection Active', inspectionStatus: 'Active', resolutionStatus: 'Open', reporter: 'Maya Alvarez', source: 'Citizen report' },
  { id: 'INC-1021', domain: 'electricity-lighting', issue: 'Street light not working', description: 'The lamp has been out for three evenings beside the bus stop.', location: 'Rosewood Bus Stop', date: '2025-06-16', time: '21:18', severity: 'WARNING', riskScore: 68, recommendation: 'Dispatch an electrical maintenance crew before the next evening peak.', status: 'Assigned', inspectionStatus: 'Completed', assignedTeam: 'Brightpath Electrical', resolutionStatus: 'Assigned', reporter: 'C. Mensah', source: 'Citizen report' },
  { id: 'INC-1018', domain: 'drainage-sanitation', issue: 'Drain blockage', description: 'Plastic waste is blocking the inlet and water is backing up onto the road.', location: 'Juniper Lane Inlet', date: '2025-06-16', time: '14:06', severity: 'CRITICAL', riskScore: 57, recommendation: 'Clear the inlet and re-check water flow after the next rainfall.', status: 'Action In Progress', inspectionStatus: 'Completed', assignedTeam: 'Waterway Response', resolutionStatus: 'Action In Progress', reporter: 'R. Singh', source: 'Citizen report' },
  { id: 'INC-1014', domain: 'school-education', issue: 'Emergency exit issue', description: 'The exit is now clear after a facilities team removed stored desks.', location: 'Cedar Grove Primary', date: '2025-06-15', time: '11:24', severity: 'WARNING', riskScore: 88, recommendation: 'Retain a clear exit path and log a routine facilities follow-up.', status: 'Resolved', inspectionStatus: 'Completed', assignedTeam: 'Northline Facilities', resolutionStatus: 'Resolved', resolutionDate: '2025-06-17', resolutionNote: 'Exit cleared, signage retained, and staff briefed.', reporter: 'Maya Alvarez', source: 'Citizen report' },
  { id: 'INC-1009', domain: 'water-supply', issue: 'Water leakage', description: 'A continuous leak is visible at the valve house entrance.', location: 'East Bank Valve House', date: '2025-06-14', time: '08:36', severity: 'WARNING', riskScore: 64, recommendation: 'Isolate the affected line and schedule a water-works repair crew.', status: 'Inspection Scheduled', inspectionStatus: 'Scheduled', resolutionStatus: 'Open', reporter: 'Maya Alvarez', source: 'Citizen report' },
];
const departmentFilterLabels: Record<DomainKey, string> = {
  'roads-highways': 'Roads', 'electricity-lighting': 'Electricity', 'water-supply': 'Water',
  'drainage-sanitation': 'Drainage', 'school-education': 'Education', 'higher-education': 'Higher Education',
  'construction-buildings': 'Construction', 'public-health': 'Health', environment: 'Environment',
  transport: 'Transport', municipality: 'Municipality', 'fire-emergency': 'Fire Safety',
};

function App() {
  const [session, setSession] = useState<{ role: Role; name: string } | null>(() => { try { return JSON.parse(localStorage.getItem(storageKeys.session) ?? 'null'); } catch { return null; } });
  const [domainKey, setDomainKey] = useState<DomainKey | null>(() => { const stored = localStorage.getItem(storageKeys.domain); return stored ? (legacyDomainMap[stored] ?? stored as DomainKey) : null; });
  const [incidents, setIncidents] = useState<Incident[]>(() => readStoredIncidents(storageKeys.incidents, seedIncidents));
  const [page, setPage] = useState<Page>('dashboard');
  const [toast, setToast] = useState('');
  const [loginRole, setLoginRole] = useState<Role>('citizen');
  const [mobileNav, setMobileNav] = useState(false);
  useEffect(() => writeStoredIncidents(storageKeys.incidents, incidents), [incidents]);
  useEffect(() => { if (!toast) return; const timer = window.setTimeout(() => setToast(''), 3200); return () => window.clearTimeout(timer); }, [toast]);
  const login = (role: Role, demo = false) => { const next = { role, name: demo ? (role === 'admin' ? 'Amina Okafor' : role === 'inspector' ? 'Daniel Mensah' : 'Maya Alvarez') : 'Jordan Lee' }; localStorage.setItem(storageKeys.session, JSON.stringify(next)); setSession(next); };
  const logout = () => { localStorage.removeItem(storageKeys.session); localStorage.removeItem(storageKeys.domain); setSession(null); setDomainKey(null); };
  const chooseDomain = (key: DomainKey) => { localStorage.setItem(storageKeys.domain, key); setDomainKey(key); setToast(`${getDomain(key).name} workspace ready`); };
  const patchIncident = (id: string, patch: Partial<Incident>) => setIncidents((all) => all.map((item) => item.id === id ? { ...item, ...patch } : item));
  const addIncident = (incident: Incident) => { setIncidents((all) => [incident, ...all]); setToast(`${incident.id} created and added to the operations queue`); };
  if (!session) return <LoginScreen role={loginRole} setRole={setLoginRole} onLogin={login} />;
  if (!domainKey) return <DomainSelection role={session.role} name={session.name} onSelect={chooseDomain} onLogout={logout} />;
  const domain = getDomain(domainKey);
  return <div className="noise min-h-[100dvh] bg-background"><AppShell role={session.role} name={session.name} domain={domain} page={page} setPage={(next) => { setPage(next); setMobileNav(false); }} onChangeDomain={() => { setDomainKey(null); localStorage.removeItem(storageKeys.domain); }} onLogout={logout} mobileNav={mobileNav} setMobileNav={setMobileNav}>
    {page === 'dashboard' && session.role === 'citizen' && <CitizenDashboard domain={domain} incidents={incidents} addIncident={addIncident} goComplaints={() => setPage('complaints')} />}
    {page === 'complaints' && session.role === 'citizen' && <Complaints incidents={incidents.filter((item) => item.source === 'Citizen report')} patchIncident={patchIncident} />}
    {page === 'dashboard' && session.role === 'inspector' && <InspectorDashboard domain={domain} incidents={incidents} patchIncident={patchIncident} setToast={setToast} />}
    {page === 'dashboard' && session.role === 'admin' && <AdminDashboard incidents={incidents} patchIncident={patchIncident} setToast={setToast} />}
    {page === 'monitor' && <Monitoring incidents={incidents} />}
    {page === 'reports' && <Reports incidents={incidents} role={session.role} />}
    {page === 'teams' && <TeamsView incidents={incidents} />}
  </AppShell>
  {toast && <div data-testid="status-toast" className="fixed bottom-5 left-1/2 z-[60] flex -translate-x-1/2 items-center gap-2 rounded-full bg-primary px-4 py-3 text-sm font-semibold text-primary-foreground shadow-xl animate-rise"><Check size={16} />{toast}</div>}</div>;
}

function Logo({ compact = false }: { compact?: boolean }) { return <div className="flex items-center gap-2.5" data-testid="brand-inspectiq"><div className="relative flex size-9 items-center justify-center rounded-xl bg-accent text-primary shadow-sm"><Crosshair size={20} strokeWidth={2.5} /><span className="absolute right-1 top-1 size-1.5 rounded-full bg-primary" /></div>{!compact && <div><div className="font-mono-ui text-[15px] font-bold tracking-[.16em]">INSPECT<span className="text-accent">IQ</span></div><div className="text-[9px] uppercase tracking-[.2em] text-muted-foreground">action intelligence</div></div>}</div>; }
function LoginScreen({ role, setRole, onLogin }: { role: Role; setRole: (role: Role) => void; onLogin: (role: Role, demo?: boolean) => void }) { const [email, setEmail] = useState(''); const [password, setPassword] = useState(''); return <main className="grid min-h-[100dvh] bg-primary lg:grid-cols-[1.1fr_.9fr]"><section className="relative hidden overflow-hidden p-10 text-primary-foreground lg:flex lg:flex-col lg:justify-between"><div className="absolute -right-40 -top-40 size-[620px] rounded-full border border-primary-foreground/10" /><Logo /><div className="relative max-w-xl animate-rise"><div className="mb-5 flex items-center gap-2 text-xs font-semibold uppercase tracking-[.22em] text-accent"><span className="size-2 rounded-full bg-accent animate-pulse-dot" />Tamil Nadu public-service operations</div><h1 className="max-w-lg text-6xl font-semibold leading-[.98] tracking-[-.06em]">From report<br /><span className="text-accent">to resolution.</span></h1><p className="mt-7 max-w-md text-base leading-7 text-primary-foreground/65">InspectIQ turns local observations into verified, assigned, and resolved action — with every handoff in view.</p></div><div className="relative flex items-center gap-8 text-xs text-primary-foreground/55"><span>12 departments</span><span className="h-px w-12 bg-primary-foreground/20" /><span>One trusted queue</span></div></section><section className="flex items-center justify-center bg-background px-5 py-10 sm:px-10"><div className="w-full max-w-[430px] animate-rise"><div className="mb-10 lg:hidden"><Logo /></div><div className="mb-8"><div className="mb-3 inline-flex rounded-full border border-border bg-card px-3 py-1 font-mono-ui text-[10px] uppercase tracking-[.2em] text-muted-foreground">Operations cockpit</div><h2 className="text-3xl font-semibold tracking-[-.04em]">Welcome back.</h2><p className="mt-2 text-sm text-muted-foreground">Smart Inspection. Faster Action. Safer Communities.</p></div><div className="space-y-4"><label className="block text-sm font-semibold">Email address<input data-testid="input-email" value={email} onChange={(e) => setEmail(e.target.value)} placeholder="you@city.gov" type="email" className="mt-2 w-full rounded-xl border border-input bg-card px-4 py-3.5 text-sm outline-none focus:border-accent" /></label><label className="block text-sm font-semibold">Password<input data-testid="input-password" value={password} onChange={(e) => setPassword(e.target.value)} placeholder="Enter your password" type="password" className="mt-2 w-full rounded-xl border border-input bg-card px-4 py-3.5 text-sm outline-none focus:border-accent" /></label><button data-testid="button-login" onClick={() => onLogin(role)} className="flex w-full items-center justify-center gap-2 rounded-xl bg-primary px-4 py-3.5 text-sm font-bold text-primary-foreground">Log in <ArrowRight size={16} /></button><button data-testid="button-demo-login" onClick={() => onLogin(role, true)} className="w-full rounded-xl border border-border bg-card px-4 py-3.5 text-sm font-bold hover:border-accent">Use demo workspace</button></div><div className="mt-9 border-t border-border pt-6"><p className="mb-3 text-xs font-semibold uppercase tracking-[.14em] text-muted-foreground">Demo role</p><div className="grid grid-cols-3 gap-2">{([['citizen', 'Citizen / User'], ['inspector', 'Inspector'], ['admin', 'Admin / Allocator']] as [Role, string][]).map(([key, label]) => <button data-testid={`button-role-${key}`} key={key} onClick={() => setRole(key)} className={`rounded-xl border px-2 py-3 text-center text-[11px] font-semibold ${role === key ? 'border-accent bg-accent/15' : 'border-border bg-card text-muted-foreground'}`}><span className={`mx-auto mb-2 block size-2 rounded-full ${role === key ? 'bg-accent' : 'bg-muted'}`} />{label}</button>)}</div><p className="mt-4 text-center text-[11px] leading-5 text-muted-foreground">Demo mode uses local browser storage. No real account or API connection required.</p></div></div></section></main>; }

function DomainSelection({ role, name, onSelect, onLogout }: { role: Role; name: string; onSelect: (key: DomainKey) => void; onLogout: () => void }) { return <main className="min-h-[100dvh] bg-background px-5 py-6 sm:px-10 sm:py-10"><header className="mx-auto flex max-w-6xl items-center justify-between"><Logo /><button data-testid="button-logout" onClick={onLogout} className="flex items-center gap-2 rounded-lg px-3 py-2 text-xs font-bold text-muted-foreground"><LogOut size={15} /> Sign out</button></header><section className="mx-auto max-w-6xl pt-14"><div className="max-w-2xl animate-rise"><div className="mb-4 flex items-center gap-2 text-xs font-semibold uppercase tracking-[.18em] text-muted-foreground"><span className="size-2 rounded-full bg-accent" /> {role === 'admin' ? 'Allocation desk' : role === 'inspector' ? 'Field workspace' : 'Community portal'}</div><h1 className="text-4xl font-semibold tracking-[-.05em] sm:text-6xl">Good morning, {name.split(' ')[0]}.<br /><span className="text-muted-foreground">What are we looking after?</span></h1><p className="mt-5 max-w-lg text-sm leading-6 text-muted-foreground">Choose a working department. InspectIQ tunes reports, checks, recommendations, and team matches around it.</p></div><div className="mt-12 grid gap-3 sm:grid-cols-2 lg:grid-cols-3">{domainConfigs.map((item, index) => <DomainCard key={item.key} domain={item} index={index} onSelect={onSelect} />)}</div></section></main>; }
function DomainCard({ domain, index, onSelect }: { domain: DomainConfig; index: number; onSelect: (key: DomainKey) => void; }) { const Icon = domain.icon; return <button data-testid={`card-domain-${domain.key}`} onClick={() => onSelect(domain.key)} className={`group relative overflow-hidden rounded-2xl border border-border bg-gradient-to-br ${domain.tint} p-5 text-left shadow-sm animate-rise animate-rise-${Math.min(index % 3 + 1, 3)} hover:-translate-y-1 hover:border-accent`}><div className="flex items-start justify-between"><div className="flex size-11 items-center justify-center rounded-xl bg-card/75 text-primary shadow-sm"><Icon size={22} /></div><ArrowRight size={16} className="text-primary opacity-0 group-hover:opacity-100" /></div><h2 className="mt-7 text-lg font-bold">{domain.name}</h2><p className="mt-1 text-xs font-semibold uppercase tracking-[.12em] text-primary/55">{domain.short}</p><p className="mt-4 max-w-xs text-sm leading-5 text-primary/70">{domain.description}</p></button>; }

function AppShell({ role, name, domain, page, setPage, onChangeDomain, onLogout, mobileNav, setMobileNav, children }: { role: Role; name: string; domain: DomainConfig; page: Page; setPage: (page: Page) => void; onChangeDomain: () => void; onLogout: () => void; mobileNav: boolean; setMobileNav: (open: boolean) => void; children: ReactNode }) { const nav: [Page, string, LucideIcon][] = [['dashboard', 'Overview', Home], ...(role === 'citizen' ? [['complaints', 'My complaints', FileCheck2] as [Page, string, LucideIcon]] : []), ['monitor', 'Live monitor', Radio], ['reports', 'Incident log', FileCheck2], ['teams', 'Teams', Users]]; const DomainIcon = domain.icon; return <div className="flex min-h-[100dvh]"><aside className={`fixed inset-y-0 left-0 z-40 w-[260px] bg-sidebar px-4 py-5 text-sidebar-foreground transition-transform md:sticky md:top-0 md:flex md:h-[100dvh] md:translate-x-0 md:flex-col ${mobileNav ? 'translate-x-0' : '-translate-x-full'}`}><div className="flex items-center justify-between px-2"><Logo /><button data-testid="button-close-nav" onClick={() => setMobileNav(false)} className="rounded-lg p-2 md:hidden"><X size={18} /></button></div><div className="mt-9 rounded-2xl border border-sidebar-border bg-sidebar-accent/55 p-3"><div className="flex items-center gap-3"><div className="flex size-10 items-center justify-center rounded-xl bg-accent text-primary"><DomainIcon size={20} /></div><div className="min-w-0"><p className="truncate text-sm font-bold">{domain.name}</p><p className="text-[10px] uppercase tracking-[.14em] text-sidebar-foreground/55">Active department</p></div></div><button data-testid="button-change-domain" onClick={onChangeDomain} className="mt-3 flex w-full items-center justify-between rounded-lg border border-sidebar-border px-2.5 py-2 text-[11px] font-semibold text-sidebar-foreground/70">Change department <ChevronDown size={13} /></button></div><div className="mt-8 flex-1"><p className="px-2 text-[10px] font-bold uppercase tracking-[.18em] text-sidebar-foreground/45">Workspace</p><nav className="mt-3 space-y-1">{nav.map(([key, label, Icon]) => <button data-testid={`nav-${key}`} key={key} onClick={() => setPage(key)} className={`flex w-full items-center gap-3 rounded-xl px-3 py-3 text-sm font-semibold ${page === key ? 'bg-accent text-primary shadow-sm' : 'text-sidebar-foreground/70 hover:bg-sidebar-accent'}`}><Icon size={17} />{label}{key === 'monitor' && <span className="ml-auto size-2 rounded-full bg-emerald-400 animate-pulse-dot" />}</button>)}</nav></div><div className="border-t border-sidebar-border pt-4"><div className="flex items-center gap-3 px-2"><div className="flex size-9 items-center justify-center rounded-full bg-sidebar-accent font-mono-ui text-xs font-bold text-accent">{name.split(' ').map((part) => part[0]).join('').slice(0, 2)}</div><div className="min-w-0 flex-1"><p className="truncate text-sm font-semibold">{name}</p><p className="truncate text-[11px] capitalize text-sidebar-foreground/50">{role === 'admin' ? 'Admin / Allocator' : role}</p></div><button data-testid="button-sidebar-logout" onClick={onLogout} className="rounded-lg p-2 text-sidebar-foreground/50"><LogOut size={15} /></button></div></div></aside>{mobileNav && <button data-testid="button-nav-overlay" aria-label="Close navigation" onClick={() => setMobileNav(false)} className="fixed inset-0 z-30 bg-primary/30 md:hidden" />}<main className="min-w-0 flex-1"><header className="sticky top-0 z-20 flex h-[72px] items-center justify-between border-b border-border bg-background/90 px-4 backdrop-blur-md sm:px-8"><div className="flex items-center gap-3"><button data-testid="button-open-nav" onClick={() => setMobileNav(true)} className="rounded-lg p-2 md:hidden"><Menu size={20} /></button><div className="md:hidden"><Logo compact /></div><div className="hidden items-center gap-2 text-sm md:flex"><span className="text-muted-foreground">Workspace /</span><b>{domain.name}</b></div></div><div className="flex items-center gap-3"><div className="hidden items-center gap-2 rounded-full border border-emerald-200 bg-emerald-50 px-3 py-1.5 text-[11px] font-bold text-emerald-800 sm:flex"><span className="size-1.5 rounded-full bg-emerald-500 animate-pulse-dot" /> Live monitoring</div><button data-testid="button-notifications" className="relative rounded-lg p-2 text-muted-foreground"><Bell size={18} /><span className="absolute right-1.5 top-1.5 size-1.5 rounded-full bg-accent" /></button></div></header><div className="mx-auto max-w-[1480px] p-4 sm:p-8">{children}</div></main></div>; }

function PageIntro({ eyebrow, title, description, action }: { eyebrow: string; title: string; description?: string; action?: ReactNode }) { return <div className="flex flex-col justify-between gap-5 sm:flex-row sm:items-end"><div><p className="mb-2 flex items-center gap-2 text-[11px] font-bold uppercase tracking-[.18em] text-muted-foreground"><span className="size-1.5 rounded-full bg-accent" />{eyebrow}</p><h1 className="text-3xl font-semibold tracking-[-.05em] sm:text-4xl">{title}</h1>{description && <p className="mt-2 max-w-2xl text-sm leading-6 text-muted-foreground">{description}</p>}</div>{action}</div>; }
function StatCard({ label, value, detail, icon: Icon, tone = 'default' }: { label: string; value: string | number; detail: string; icon: LucideIcon; tone?: string }) { const colors: Record<string, string> = { default: 'bg-card', critical: 'bg-red-50 border-red-100', safe: 'bg-emerald-50 border-emerald-100', accent: 'bg-accent/15 border-accent/25' }; return <div data-testid={`stat-${label.toLowerCase().replaceAll(' ', '-')}`} className={`rounded-2xl border border-card-border p-4 shadow-sm ${colors[tone] ?? colors.default}`}><div className="flex items-center justify-between"><p className="text-[11px] font-bold uppercase tracking-[.12em] text-muted-foreground">{label}</p><Icon size={16} className="text-muted-foreground" /></div><div className="mt-4 flex items-end justify-between"><p className="font-mono-ui text-3xl font-bold tracking-[-.08em]">{value}</p><p className="text-right text-[11px] font-semibold text-muted-foreground">{detail}</p></div></div>; }
function SeverityBadge({ severity }: { severity: Severity }) { const tone = severityTone(severity); return <span data-testid={`status-severity-${severity.toLowerCase()}`} className={`inline-flex items-center gap-1.5 rounded-full border px-2 py-1 text-[10px] font-bold uppercase tracking-[.08em] ${tone.className}`}><span className={`size-1.5 rounded-full ${tone.dot}`} />{tone.label}</span>; }
function StatusBadge({ status }: { status: IncidentStatus }) { const safe = status === 'Resolved'; const active = status === 'Action In Progress' || status === 'Inspection Active' || status === 'Team Accepted'; return <span className={`inline-flex rounded-full border px-2 py-1 text-[10px] font-bold ${safe ? 'border-emerald-200 bg-emerald-50 text-emerald-800' : active ? 'border-sky-200 bg-sky-50 text-sky-800' : 'border-border bg-muted text-muted-foreground'}`}>{status}</span>; }
function IncidentRow({ incident, action }: { incident: Incident; action?: ReactNode }) { const domain = getDomain(incident.domain); const Icon = domain.icon; return <div data-testid={`row-incident-${incident.id}`} className="flex flex-col gap-3 border-b border-border py-4 last:border-0 sm:flex-row sm:items-center sm:justify-between"><div className="flex min-w-0 items-start gap-3"><div className="mt-0.5 flex size-9 shrink-0 items-center justify-center rounded-xl bg-muted text-primary"><Icon size={17} /></div><div className="min-w-0"><div className="flex flex-wrap items-center gap-2"><span className="font-mono-ui text-xs font-bold text-primary">{incident.id}</span><SeverityBadge severity={incident.severity} /></div><p className="mt-1 truncate text-sm font-bold">{incident.issue} <span className="font-normal text-muted-foreground">· {domain.name}</span></p><p className="mt-1 flex items-center gap-1 text-xs text-muted-foreground"><MapPin size={12} />{incident.location}<span className="mx-1">·</span>{incident.date}</p></div></div><div className="flex items-center justify-between gap-3 pl-12 sm:justify-end sm:pl-0"><div className="text-right"><StatusBadge status={incident.status} />{incident.assignedTeam && <p className="mt-1 text-[10px] text-muted-foreground">{incident.assignedTeam}</p>}</div>{action}</div></div>; }

function CitizenDashboard({ domain, incidents, addIncident, goComplaints }: { domain: DomainConfig; incidents: Incident[]; addIncident: (incident: Incident) => void; goComplaints: () => void }) { const [form, setForm] = useState({ issue: domain.issues[0], description: '', location: domain.sampleLocations[0], photo: '', coordinates: '' }); const [submitted, setSubmitted] = useState(''); const own = incidents.filter((item) => item.source === 'Citizen report'); const useLocation = () => { if (!navigator.geolocation) return setForm({ ...form, coordinates: 'Location unavailable in this browser' }); navigator.geolocation.getCurrentPosition((p) => setForm({ ...form, coordinates: `${p.coords.latitude.toFixed(4)}, ${p.coords.longitude.toFixed(4)}` }), () => setForm({ ...form, coordinates: 'Location permission was not granted' })); }; const report = () => { if (!form.description.trim() || !form.location.trim()) return; const parts = nowParts(); const risk = riskForIssue(form.issue, domain.key, form.description); const incident: Incident = { id: nextIncidentId(incidents), domain: domain.key, issue: form.issue, description: form.description, location: form.location, coordinates: form.coordinates, date: parts.date, time: parts.time, severity: risk.severity, riskScore: risk.score, recommendation: domain.recommendation, status: 'Reported', inspectionStatus: 'Pending', resolutionStatus: 'Open', reporter: 'Maya Alvarez', source: 'Citizen report', photo: form.photo }; addIncident(incident); setSubmitted(incident.id); setForm({ issue: domain.issues[0], description: '', location: domain.sampleLocations[0], photo: '', coordinates: '' }); }; return <div className="space-y-7 animate-rise"><PageIntro eyebrow="Community desk" title={`Keep ${domain.name.toLowerCase()} moving.`} description="Submit a clear observation and follow every handoff until the issue is resolved." action={<div className="flex items-center gap-2 rounded-full border border-emerald-200 bg-emerald-50 px-3 py-2 text-xs font-bold text-emerald-800"><span className="size-2 rounded-full bg-emerald-500 animate-pulse-dot" /> Your reports are tracked</div>} /><div className="grid gap-3 sm:grid-cols-3"><StatCard label="Submitted" value={own.length} detail="shared queue" icon={Send} tone="accent" /><StatCard label="Open" value={own.filter((item) => item.status !== 'Resolved').length} detail="being handled" icon={Clock3} /><StatCard label="Resolved" value={own.filter((item) => item.status === 'Resolved').length} detail="with record" icon={Check} tone="safe" /></div><div className="grid gap-6 xl:grid-cols-[1.15fr_.85fr]"><section className="rounded-2xl border border-card-border bg-card p-5 shadow-sm sm:p-6"><div className="flex items-center justify-between"><div><h2 className="text-lg font-bold">Report an issue</h2><p className="mt-1 text-xs text-muted-foreground">A precise report helps the right team move sooner.</p></div><div className="rounded-xl bg-accent/15 p-2.5 text-primary"><FilePlus2 size={19} /></div></div>{submitted && <div data-testid="status-report-success" className="mt-5 flex items-start gap-3 rounded-xl border border-emerald-200 bg-emerald-50 p-4 text-sm text-emerald-900"><Check size={17} /><div><p className="font-bold">Report received: {submitted}</p><p className="mt-1 text-xs">Your complaint is now in the shared inspection queue.</p></div><button data-testid="button-dismiss-success" onClick={() => setSubmitted('')} className="ml-auto"><X size={15} /></button></div>}<div className="mt-6 grid gap-4 sm:grid-cols-2"><label className="text-xs font-bold">Department problem<select data-testid="select-issue-type" value={form.issue} onChange={(e) => setForm({ ...form, issue: e.target.value })} className="mt-2 w-full rounded-xl border border-input bg-background px-3 py-3 text-sm outline-none">{domain.issues.map((issue) => <option key={issue}>{issue}</option>)}</select></label><label className="text-xs font-bold">Location<input data-testid="input-report-location" value={form.location} onChange={(e) => setForm({ ...form, location: e.target.value })} className="mt-2 w-full rounded-xl border border-input bg-background px-3 py-3 text-sm outline-none" /></label></div><label className="mt-4 block text-xs font-bold">What did you notice?<textarea data-testid="input-report-description" value={form.description} onChange={(e) => setForm({ ...form, description: e.target.value })} rows={4} placeholder={`Describe the ${domain.name.toLowerCase()} issue...`} className="mt-2 w-full resize-none rounded-xl border border-input bg-background px-3 py-3 text-sm outline-none" /></label><div className="mt-4 grid gap-3 sm:grid-cols-[1fr_auto]"><label className="flex cursor-pointer items-center gap-3 rounded-xl border border-dashed border-input bg-background p-3"><Camera size={18} className="text-muted-foreground" /><span className="min-w-0 flex-1 text-xs font-semibold"><span className="block">Add photo evidence</span><span className="font-normal text-muted-foreground">{form.photo || 'Optional · JPG or PNG'}</span></span><input data-testid="input-report-photo" type="file" accept="image/*" capture="environment" className="hidden" onChange={(e) => setForm({ ...form, photo: e.target.files?.[0]?.name ?? '' })} /></label><button data-testid="button-use-location" onClick={useLocation} className="flex items-center justify-center gap-2 rounded-xl border border-input bg-background px-4 py-3 text-xs font-bold"><Navigation size={15} /> Use current location</button></div>{form.coordinates && <p data-testid="text-report-coordinates" className="mt-2 font-mono-ui text-[10px] text-muted-foreground">Coordinates recorded: {form.coordinates}</p>}<button data-testid="button-submit-report" onClick={report} disabled={!form.description.trim()} className="mt-5 flex w-full items-center justify-center gap-2 rounded-xl bg-primary px-4 py-3.5 text-sm font-bold text-primary-foreground disabled:opacity-40"><Send size={16} /> Submit report</button></section><section className="rounded-2xl border border-card-border bg-card p-5 shadow-sm sm:p-6"><div className="flex items-start justify-between"><div><h2 className="text-lg font-bold">Recent reports</h2><p className="mt-1 text-xs text-muted-foreground">Your latest signal through the queue.</p></div><button data-testid="button-view-all-reports" onClick={goComplaints} className="text-xs font-bold text-primary underline decoration-accent decoration-2 underline-offset-4">View all</button></div><div className="mt-3">{own.slice(0, 4).map((item) => <IncidentRow key={item.id} incident={item} />)}{own.length === 0 && <EmptyState title="No complaints yet" text="Your submitted reports will appear here." />}</div></section></div><Timeline /></div>; }
function Timeline() { const stages = ['Complaint Submitted', 'Inspection Scheduled', 'Inspection Active', 'Inspection Completed', 'Team Assigned', 'Action In Progress', 'Resolved', 'Citizen Feedback']; return <section className="rounded-2xl border border-card-border bg-card p-5 shadow-sm sm:p-6"><div className="flex items-center gap-3"><Activity size={18} className="text-accent-foreground" /><div><h2 className="font-bold">One shared lifecycle</h2><p className="text-xs text-muted-foreground">Every handoff is visible to the community.</p></div></div><div className="mt-6 grid gap-2 sm:grid-cols-4 lg:grid-cols-8">{stages.map((stage, index) => <div key={stage} className="flex items-center gap-2 text-xs font-semibold text-muted-foreground"><span className="flex size-7 shrink-0 items-center justify-center rounded-full bg-muted font-mono-ui text-[10px]">{index + 1}</span>{stage}</div>)}</div></section>; }

function Complaints({ incidents, patchIncident }: { incidents: Incident[]; patchIncident: (id: string, patch: Partial<Incident>) => void }) { const [selected, setSelected] = useState<Incident | null>(null); if (selected) return <ComplaintDetail incident={incidents.find((item) => item.id === selected.id) ?? selected} onBack={() => setSelected(null)} patchIncident={patchIncident} />; return <div className="space-y-7 animate-rise"><PageIntro eyebrow="Citizen portal" title="My complaints" description="Follow your reports across inspection, assignment, action, and resolution." /><section className="rounded-2xl border border-card-border bg-card p-5 shadow-sm sm:p-6"><div className="mb-3 flex items-center justify-between"><h2 className="text-lg font-bold">Track issues</h2><span className="font-mono-ui text-xs text-muted-foreground">{incidents.length} records</span></div>{incidents.map((item) => <IncidentRow key={item.id} incident={item} action={<button data-testid={`button-view-complaint-${item.id}`} onClick={() => setSelected(item)} className="rounded-lg border border-border px-3 py-2 text-xs font-bold hover:border-accent">View details</button>} />)}{incidents.length === 0 && <EmptyState title="No complaints found" text="Use Report an issue to send your first public-service signal." />}</section></div>; }
function ComplaintDetail({ incident, onBack, patchIncident }: { incident: Incident; onBack: () => void; patchIncident: (id: string, patch: Partial<Incident>) => void }) { const [rating, setRating] = useState(incident.feedback?.rating ?? 0); const [resolved, setResolved] = useState(incident.feedback?.resolved ?? true); const [text, setText] = useState(incident.feedback?.text ?? ''); const stages: IncidentStatus[] = ['Reported', 'Inspection Scheduled', 'Inspection Active', 'Inspection Completed', 'Assigned', 'Team Accepted', 'Action In Progress', 'Resolved']; const stageIndex = Math.max(0, stages.indexOf(incident.status)); return <div className="space-y-7 animate-rise"><button data-testid="button-back-complaints" onClick={onBack} className="text-xs font-bold text-muted-foreground">← Back to my complaints</button><PageIntro eyebrow={incident.id} title={incident.issue} description={`${getDomain(incident.domain).name} · ${incident.location}`} action={<SeverityBadge severity={incident.severity} />} /><div className="grid gap-6 xl:grid-cols-[1fr_.75fr]"><section className="rounded-2xl border border-card-border bg-card p-5 shadow-sm sm:p-6"><div className="flex items-center justify-between"><h2 className="font-bold">Tracking timeline</h2><StatusBadge status={incident.status} /></div><div className="mt-6 space-y-4">{['Complaint Submitted', 'Inspection Scheduled', 'Inspection Active', 'Inspection Completed', 'Team Assigned', 'Action In Progress', 'Resolved', 'Citizen Feedback'].map((label, index) => <div data-testid={`timeline-stage-${index}`} key={label} className={`flex items-center gap-3 ${index <= stageIndex ? 'text-primary' : 'text-muted-foreground/50'}`}><span className={`flex size-8 items-center justify-center rounded-full border text-xs font-bold ${index <= stageIndex ? 'border-accent bg-accent/20' : 'border-border bg-muted'}`}>{index < stageIndex ? <Check size={14} /> : index + 1}</span><div><p className="text-sm font-bold">{label}</p>{index === stageIndex && <p className="text-xs text-muted-foreground">Current stage · shared with the response team</p>}</div></div>)}</div></section><section className="space-y-4"><div className="rounded-2xl border border-card-border bg-card p-5 shadow-sm"><h2 className="font-bold">Report record</h2><p className="mt-3 text-sm leading-6 text-muted-foreground">{incident.description}</p><div className="mt-4 grid gap-3 text-xs sm:grid-cols-2"><div><span className="text-muted-foreground">Submitted</span><b className="mt-1 block">{incident.date} · {incident.time}</b></div><div><span className="text-muted-foreground">Assigned team</span><b className="mt-1 block">{incident.assignedTeam ?? 'Awaiting allocation'}</b></div></div>{incident.status === 'Resolved' && <div className="mt-5 rounded-xl bg-emerald-50 p-4 text-sm"><p className="font-bold text-emerald-900">Resolved {incident.resolutionDate}</p><p className="mt-1 text-emerald-900/75">{incident.resolutionNote ?? 'The response team confirmed completion.'}</p></div>}</div>{incident.status === 'Resolved' && <FeedbackForm rating={rating} setRating={setRating} resolved={resolved} setResolved={setResolved} text={text} setText={setText} onSubmit={() => patchIncident(incident.id, { feedback: { resolved, rating, text, submittedAt: nowParts().date } })} />}</section></div></div>; }
function FeedbackForm({ rating, setRating, resolved, setResolved, text, setText, onSubmit }: { rating: number; setRating: (n: number) => void; resolved: boolean; setResolved: (b: boolean) => void; text: string; setText: (s: string) => void; onSubmit: () => void }) { return <section className="rounded-2xl border border-card-border bg-card p-5 shadow-sm"><h2 className="font-bold">How did we do?</h2><p className="mt-1 text-xs text-muted-foreground">Your feedback closes the public-service loop.</p><div className="mt-4 flex gap-2"><button data-testid="button-feedback-yes" onClick={() => setResolved(true)} className={`rounded-lg border px-3 py-2 text-xs font-bold ${resolved ? 'border-accent bg-accent/20' : 'border-border'}`}>Yes</button><button data-testid="button-feedback-no" onClick={() => setResolved(false)} className={`rounded-lg border px-3 py-2 text-xs font-bold ${!resolved ? 'border-accent bg-accent/20' : 'border-border'}`}>No</button></div><div className="mt-4 flex gap-1">{[1, 2, 3, 4, 5].map((n) => <button data-testid={`button-rating-${n}`} key={n} onClick={() => setRating(n)} className={`rounded p-1 ${n <= rating ? 'text-accent' : 'text-muted-foreground/30'}`}><Star size={20} fill="currentColor" /></button>)}</div><textarea data-testid="input-feedback-text" value={text} onChange={(e) => setText(e.target.value)} placeholder="Add a short note (optional)" rows={3} className="mt-3 w-full rounded-xl border border-input bg-background p-3 text-sm outline-none" /><button data-testid="button-submit-feedback" onClick={onSubmit} disabled={!rating} className="mt-3 flex w-full items-center justify-center gap-2 rounded-xl bg-primary px-4 py-3 text-sm font-bold text-primary-foreground disabled:opacity-40"><Send size={15} /> Submit feedback</button></section>; }

function InspectorDashboard({ domain, incidents, patchIncident, setToast }: { domain: DomainConfig; incidents: Incident[]; patchIncident: (id: string, patch: Partial<Incident>) => void; setToast: (message: string) => void }) { const queue = incidents.filter((item) => item.status === 'Reported' || item.status === 'Inspection Scheduled' || item.status === 'Inspection Active'); const [selectedId, setSelectedId] = useState(queue[0]?.id ?? ''); const selected = incidents.find((item) => item.id === selectedId); const [notes, setNotes] = useState(''); const [photo, setPhoto] = useState(''); const [checks, setChecks] = useState<Record<string, boolean>>({}); const [analysis, setAnalysis] = useState<AnalysisResult | null>(null); const [busy, setBusy] = useState(false); const start = () => { if (!selected) return; patchIncident(selected.id, { status: 'Inspection Active', inspectionStatus: 'Active' }); setToast(`${selected.id} is now Inspection Active`); }; const run = () => { if (!selected) return; setBusy(true); window.setTimeout(() => { setAnalysis(analyzeDemo(selected.domain, selected.issue, selected.description)); setBusy(false); }, 500); }; const complete = () => { if (!selected || !analysis) return; patchIncident(selected.id, { status: 'Inspection Completed', inspectionStatus: 'Completed', inspectionPhoto: photo, inspectionNotes: notes, inspectionFindings: analysis.findings, severity: analysis.severity, riskScore: analysis.safetyScore, recommendation: analysis.recommendation }); setAnalysis(null); setToast(`${selected.id} inspection completed`); }; return <div className="space-y-7 animate-rise"><PageIntro eyebrow="Field workspace" title="Inspection queue" description={`Citizen reports needing a ${domain.name.toLowerCase()} inspection. Select the existing report to preserve the handoff.`} action={<div className="rounded-full border border-accent/30 bg-accent/10 px-3 py-2 text-xs font-bold">{queue.length} awaiting field action</div>} /><div className="grid gap-6 xl:grid-cols-[.75fr_1.25fr]"><section className="rounded-2xl border border-card-border bg-card p-5 shadow-sm"><h2 className="font-bold">Reports to inspect</h2><div className="mt-4 space-y-2">{queue.map((item) => <button data-testid={`button-select-inspection-${item.id}`} key={item.id} onClick={() => { setSelectedId(item.id); setAnalysis(null); }} className={`w-full rounded-xl border p-3 text-left ${selectedId === item.id ? 'border-accent bg-accent/10' : 'border-border'}`}><div className="flex items-center justify-between"><span className="font-mono-ui text-xs font-bold">{item.id}</span><SeverityBadge severity={item.severity} /></div><p className="mt-2 text-sm font-bold">{item.issue}</p><p className="mt-1 text-xs text-muted-foreground">{item.location}</p></button>)}{queue.length === 0 && <EmptyState title="Queue clear" text="New citizen reports will appear here." />}</div></section>{selected ? <section className="rounded-2xl border border-card-border bg-card p-5 shadow-sm sm:p-6"><div className="flex flex-wrap items-start justify-between gap-3"><div><p className="font-mono-ui text-xs font-bold text-primary">{selected.id}</p><h2 className="mt-1 text-xl font-bold">{selected.issue}</h2><p className="mt-1 flex items-center gap-1 text-xs text-muted-foreground"><MapPin size={12} />{selected.location}</p></div><button data-testid="button-start-inspection" onClick={start} className="flex items-center gap-2 rounded-xl bg-primary px-3 py-2 text-xs font-bold text-primary-foreground"><ClipboardCheck size={15} /> Start inspection</button></div><div className="mt-5 rounded-xl bg-muted/60 p-4 text-sm leading-6"><p className="font-bold">Citizen description</p><p className="mt-1 text-muted-foreground">{selected.description}</p>{selected.coordinates && <p className="mt-2 font-mono-ui text-[10px] text-muted-foreground">Coordinates: {selected.coordinates}</p>}</div><div className="mt-6 grid gap-4 sm:grid-cols-2"><div><p className="text-xs font-bold">Department checklist</p><div className="mt-3 space-y-2">{domain.checklist.map((check) => <label key={check} className="flex items-center gap-2 rounded-lg border border-border p-2 text-xs"><input type="checkbox" checked={Boolean(checks[check])} onChange={(e) => setChecks({ ...checks, [check]: e.target.checked })} />{check}</label>)}</div></div><div><label className="text-xs font-bold">Inspection notes<textarea data-testid="input-inspection-notes" value={notes} onChange={(e) => setNotes(e.target.value)} rows={5} className="mt-2 w-full rounded-xl border border-input bg-background p-3 text-sm outline-none" /></label><label className="mt-3 flex cursor-pointer items-center gap-2 rounded-xl border border-dashed border-input p-3 text-xs font-bold"><Camera size={16} /> {photo || 'Upload inspection photo'}<input data-testid="input-inspection-photo" type="file" accept="image/*" className="hidden" onChange={(e) => setPhoto(e.target.files?.[0]?.name ?? '')} /></label></div></div><div className="mt-6 flex flex-wrap gap-3"><button data-testid="button-run-demo-ai" onClick={run} className="flex items-center gap-2 rounded-xl border border-accent bg-accent/15 px-4 py-3 text-xs font-bold"><Sparkles size={15} /> {busy ? 'Analysing demo evidence…' : 'Run demo AI analysis'}</button>{analysis && <button data-testid="button-complete-inspection" onClick={complete} className="flex items-center gap-2 rounded-xl bg-primary px-4 py-3 text-xs font-bold text-primary-foreground"><Check size={15} /> Complete inspection</button>}</div>{analysis && <AnalysisPanel analysis={analysis} />}</section> : <EmptyState title="Select a citizen report" text="The primary path is to inspect the submitted record, not create a duplicate." />}</div></div>; }
function AnalysisPanel({ analysis }: { analysis: AnalysisResult }) { return <div className="mt-5 rounded-2xl border border-accent/30 bg-accent/10 p-4"><div className="flex items-center justify-between"><p className="text-xs font-bold uppercase tracking-[.15em]">Demo analysis</p><span className="font-mono-ui text-sm font-bold">{analysis.confidence}% confidence</span></div><p className="mt-3 text-sm font-bold">{analysis.issueDetected} · {analysis.severity}</p><p className="mt-1 text-xs text-muted-foreground">{analysis.recommendation}</p><div className="mt-3 flex flex-wrap gap-2">{analysis.findings.map((finding) => <span key={finding} className="rounded-lg bg-card px-2 py-1 text-[11px]">{finding}</span>)}</div></div>; }

function AdminDashboard({ incidents, patchIncident, setToast }: { incidents: Incident[]; patchIncident: (id: string, patch: Partial<Incident>) => void; setToast: (message: string) => void }) { const [dept, setDept] = useState('all'); const [severity, setSeverity] = useState<'all' | Severity>('all'); const [selectedId, setSelectedId] = useState(''); const filtered = incidents.filter((item) => (dept === 'all' || item.domain === dept) && (severity === 'all' || item.severity === severity)); const stats: [string, number, LucideIcon, string][] = [['Total Complaints', incidents.length, FileCheck2, 'accent'], ['Pending Inspection', incidents.filter((i) => i.status === 'Reported' || i.status === 'Inspection Scheduled').length, Clock3, 'default'], ['Inspection Active', incidents.filter((i) => i.status === 'Inspection Active').length, Activity, 'critical'], ['Inspections Completed', incidents.filter((i) => i.status === 'Inspection Completed').length, ClipboardCheck, 'safe'], ['Action In Progress', incidents.filter((i) => i.status === 'Action In Progress').length, Gauge, 'default'], ['Resolved', incidents.filter((i) => i.status === 'Resolved').length, Check, 'safe'], ['Feedback Received', incidents.filter((i) => Boolean(i.feedback)).length, Star, 'accent']]; const selected = incidents.find((i) => i.id === selectedId); const assign = (item: Incident) => { const team = recommendTeam(item.domain, item.severity, getDomain(item.domain).recommendedSkill); patchIncident(item.id, { assignedTeam: team.name, status: 'Assigned', resolutionStatus: 'Assigned' }); setToast(`${team.name} recommended for ${item.id}`); }; const advance = (item: Incident) => { const next: Partial<Record<IncidentStatus, IncidentStatus>> = { Assigned: 'Team Accepted', 'Team Accepted': 'Action In Progress', 'Action In Progress': 'Resolved' }; const status = next[item.status]; if (!status) return; patchIncident(item.id, status === 'Resolved' ? { status, resolutionStatus: 'Resolved', resolutionDate: nowParts().date, resolutionNote: 'Work completed and verified by the response team.' } : { status, resolutionStatus: status }); setToast(`${item.id} moved to ${status}`); }; return <div className="space-y-7 animate-rise"><PageIntro eyebrow="Allocation desk" title="Complaints control room" description="Match verified incidents to the right response team, then keep resolution accountable." /><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4 xl:grid-cols-7">{stats.map(([label, value, Icon, tone]) => <StatCard key={label} label={label} value={value} detail="live records" icon={Icon} tone={tone} />)}</div><section className="rounded-2xl border border-card-border bg-card p-5 shadow-sm sm:p-6"><div className="flex flex-col gap-3 lg:flex-row lg:items-center lg:justify-between"><div><h2 className="text-lg font-bold">Allocation queue</h2><p className="mt-1 text-xs text-muted-foreground">Recommendation weighs department skill, availability, distance, and workload.</p></div><div className="flex flex-wrap gap-2"><select data-testid="select-department-filter" value={dept} onChange={(e) => setDept(e.target.value)} className="rounded-xl border border-input bg-background px-3 py-2 text-xs"><option value="all">All Departments</option>{domainConfigs.map((item) => <option key={item.key} value={item.key}>{item.name.replace(' & Street Lighting', '').replace(' & Highways', '').replace(' & Sanitation', '').replace(' Education', '')}</option>)}</select><select data-testid="select-admin-severity-filter" value={severity} onChange={(e) => setSeverity(e.target.value as 'all' | Severity)} className="rounded-xl border border-input bg-background px-3 py-2 text-xs"><option value="all">All severity</option><option value="SAFE">Safe</option><option value="WARNING">Warning</option><option value="CRITICAL">Critical</option></select></div></div><div className="mt-5 overflow-x-auto"><table className="w-full min-w-[900px] text-left text-xs"><thead className="border-b border-border text-[10px] uppercase tracking-[.14em] text-muted-foreground"><tr><th className="pb-3">Incident</th><th className="pb-3">Department / issue</th><th className="pb-3">Location</th><th className="pb-3">Result</th><th className="pb-3">Team / capacity</th><th className="pb-3">Action</th></tr></thead><tbody>{filtered.map((item) => { const team = recommendTeam(item.domain, item.severity, getDomain(item.domain).recommendedSkill); return <tr data-testid={`row-admin-${item.id}`} key={item.id} className="border-b border-border/70"><td className="py-4 align-top"><span className="font-mono-ui font-bold">{item.id}</span><div className="mt-1"><SeverityBadge severity={item.severity} /></div></td><td className="py-4 align-top"><b>{getDomain(item.domain).name}</b><p className="mt-1 text-muted-foreground">{item.issue}</p></td><td className="py-4 align-top text-muted-foreground">{item.location}</td><td className="py-4 align-top"><StatusBadge status={item.status} /><p className="mt-2 max-w-[170px] text-muted-foreground">{item.inspectionFindings?.[0] ?? 'Awaiting inspection result'}</p></td><td className="py-4 align-top"><b>{item.assignedTeam ?? team.name}</b><p className="mt-1 text-muted-foreground">{team.availability} · {team.distance} · {team.workload} open jobs</p>{item.feedback && <p className="mt-1 text-accent-foreground">Feedback: {item.feedback.rating}/5</p>}</td><td className="py-4 align-top"><div className="flex flex-wrap gap-2">{!item.assignedTeam && <button data-testid={`button-find-team-${item.id}`} onClick={() => assign(item)} className="rounded-lg bg-primary px-2.5 py-2 text-[10px] font-bold text-primary-foreground">Find Best Team</button>}{item.assignedTeam && item.status !== 'Resolved' && <button data-testid={`button-advance-${item.id}`} onClick={() => advance(item)} className="rounded-lg border border-accent bg-accent/15 px-2.5 py-2 text-[10px] font-bold">{item.status === 'Action In Progress' ? 'Mark Resolved' : item.status === 'Assigned' ? 'Team Accepted' : 'Advance status'}</button>}<button data-testid={`button-open-admin-${item.id}`} onClick={() => setSelectedId(item.id)} className="rounded-lg border border-border px-2.5 py-2 text-[10px] font-bold">Details</button></div></td></tr>; })}</tbody></table>{filtered.length === 0 && <EmptyState title="No matching incidents" text="Try a different department or severity filter." />}</div>{selected && <ResolutionPanel incident={selected} patchIncident={patchIncident} onClose={() => setSelectedId('')} />}</section><MapPanel incidents={filtered} /></div>; }
function ResolutionPanel({ incident, patchIncident, onClose }: { incident: Incident; patchIncident: (id: string, patch: Partial<Incident>) => void; onClose: () => void }) { const [note, setNote] = useState(incident.resolutionNote ?? ''); const [date, setDate] = useState(incident.resolutionDate ?? nowParts().date); const [photo, setPhoto] = useState(incident.resolutionPhoto ?? ''); return <div className="mt-6 rounded-2xl border border-accent/30 bg-accent/10 p-5"><div className="flex items-center justify-between"><h3 className="font-bold">Resolution record · {incident.id}</h3><button data-testid="button-close-resolution" onClick={onClose}><X size={16} /></button></div><div className="mt-4 grid gap-3 sm:grid-cols-3"><label className="text-xs font-bold">Resolution date<input data-testid="input-resolution-date" type="date" value={date} onChange={(e) => setDate(e.target.value)} className="mt-2 w-full rounded-lg border border-input bg-background p-2 text-sm" /></label><label className="text-xs font-bold">Responsible team<input data-testid="input-resolution-team" value={incident.assignedTeam ?? ''} readOnly className="mt-2 w-full rounded-lg border border-input bg-background p-2 text-sm" /></label><label className="text-xs font-bold">Resolution photo<input data-testid="input-resolution-photo" type="file" accept="image/*" onChange={(e) => setPhoto(e.target.files?.[0]?.name ?? '')} className="mt-2 w-full rounded-lg border border-input bg-background p-2 text-xs" /></label></div><textarea data-testid="input-resolution-note" value={note} onChange={(e) => setNote(e.target.value)} rows={3} placeholder="What was done?" className="mt-3 w-full rounded-lg border border-input bg-background p-3 text-sm" /><button data-testid="button-save-resolution" onClick={() => { patchIncident(incident.id, { status: 'Resolved', resolutionStatus: 'Resolved', resolutionDate: date, resolutionNote: note, resolutionPhoto: photo }); onClose(); }} className="mt-3 rounded-xl bg-primary px-4 py-3 text-xs font-bold text-primary-foreground">Save resolution</button></div>; }

function MapPanel({ incidents }: { incidents: Incident[] }) { return <section className="panel-grid relative overflow-hidden rounded-2xl border border-card-border bg-card p-5 shadow-sm sm:p-6"><div className="flex items-start justify-between"><div><p className="text-[11px] font-bold uppercase tracking-[.16em] text-muted-foreground">Live geography</p><h2 className="mt-1 text-lg font-bold">Operations map</h2></div><div className="flex gap-3 text-[10px] font-bold"><span className="flex items-center gap-1"><i className="size-2 rounded-full bg-red-500" /> Critical</span><span className="flex items-center gap-1"><i className="size-2 rounded-full bg-amber-500" /> Warning</span><span className="flex items-center gap-1"><i className="size-2 rounded-full bg-emerald-500" /> Safe</span></div></div><div className="relative mt-5 h-52 overflow-hidden rounded-xl border border-border bg-[#e8e1d2]"><div className="absolute inset-0 opacity-50" style={{ backgroundImage: 'linear-gradient(32deg, transparent 48%, #b9b19f 49%, #b9b19f 51%, transparent 52%), linear-gradient(122deg, transparent 48%, #c7bfad 49%, #c7bfad 51%, transparent 52%)', backgroundSize: '130px 90px' }} />{incidents.slice(0, 12).map((item, index) => <div data-testid={`map-marker-${item.id}`} key={item.id} className={`absolute flex size-7 items-center justify-center rounded-full border-2 border-card text-[9px] font-bold text-white shadow-md ${item.severity === 'CRITICAL' ? 'bg-red-600' : item.severity === 'WARNING' ? 'bg-amber-500' : 'bg-emerald-600'}`} style={{ left: `${12 + (index * 19) % 76}%`, top: `${18 + (index * 31) % 60}%` }}>{index + 1}</div>)}</div></section>; }
function Monitoring({ incidents }: { incidents: Incident[] }) { return <div className="space-y-7 animate-rise"><PageIntro eyebrow="Situational view" title="Live monitor" description="A map-style overview of the same shared incident records." /><MapPanel incidents={incidents} /><section className="rounded-2xl border border-card-border bg-card p-5 shadow-sm"><div className="flex items-center gap-2"><Radio size={17} className="text-accent-foreground" /><h2 className="font-bold">Active signals</h2></div><div className="mt-3">{incidents.filter((i) => i.status !== 'Resolved').map((item) => <IncidentRow key={item.id} incident={item} />)}</div></section></div>; }
function Reports({ incidents, role }: { incidents: Incident[]; role: Role }) { const [query, setQuery] = useState(''); const [severity, setSeverity] = useState<'all' | Severity>('all'); const filtered = incidents.filter((i) => `${i.id} ${i.issue} ${i.location} ${getDomain(i.domain).name}`.toLowerCase().includes(query.toLowerCase()) && (severity === 'all' || i.severity === severity)); return <div className="space-y-7 animate-rise"><PageIntro eyebrow="Record archive" title="Incident log" description="Every record retains its source, evidence, risk, and next action." action={<span className="font-mono-ui text-xs text-muted-foreground">{role === 'admin' ? 'Allocator view' : 'Read-only history'}</span>} /><section className="rounded-2xl border border-card-border bg-card p-5 shadow-sm sm:p-6"><div className="flex flex-col gap-3 sm:flex-row"><label className="relative flex-1"><Search size={15} className="absolute left-3 top-3.5 text-muted-foreground" /><input data-testid="input-search-incidents" value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Search incident, issue, or location" className="w-full rounded-xl border border-input bg-background py-3 pl-9 pr-3 text-sm outline-none" /></label><select data-testid="select-severity-filter" value={severity} onChange={(e) => setSeverity(e.target.value as 'all' | Severity)} className="rounded-xl border border-input bg-background px-3 py-3 text-sm"><option value="all">All severities</option><option value="CRITICAL">Critical</option><option value="WARNING">Warning</option><option value="SAFE">Safe</option></select></div><div className="mt-5">{filtered.map((item) => <IncidentRow key={item.id} incident={item} />)}{filtered.length === 0 && <EmptyState title="No matching incidents" text="Try a different issue, location, or severity." />}</div></section></div>; }
function TeamsView({ incidents }: { incidents: Incident[] }) { return <div className="space-y-7 animate-rise"><PageIntro eyebrow="People and capacity" title="Response teams" description="A shared view of skill coverage, current workload, and assignment readiness." /><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">{teams.map((team) => <div data-testid={`card-team-${team.id}`} key={team.id} className="rounded-2xl border border-card-border bg-card p-5 shadow-sm"><div className="flex items-start justify-between"><div className="flex size-10 items-center justify-center rounded-xl bg-primary text-accent"><Users size={18} /></div><span className="rounded-full bg-emerald-50 px-2 py-1 text-[10px] font-bold text-emerald-800">{team.availability}</span></div><h2 className="mt-5 font-bold">{team.name}</h2><p className="mt-1 text-xs text-muted-foreground">{team.distance} from central depot · {team.workload} open jobs</p><div className="mt-5 flex flex-wrap gap-1.5">{team.skills.map((skill) => <span key={skill} className="rounded-md bg-muted px-2 py-1 text-[10px] font-semibold">{skill}</span>)}</div></div>)}</div><section className="rounded-2xl border border-card-border bg-card p-5 shadow-sm"><h2 className="text-lg font-bold">Assignment health</h2><div className="mt-5 grid gap-4 sm:grid-cols-3"><div className="rounded-xl bg-muted/60 p-4"><p className="text-xs font-bold text-muted-foreground">Coverage</p><p className="mt-2 font-mono-ui text-2xl font-bold">12 / 12</p><p className="mt-1 text-[11px] text-muted-foreground">departments covered</p></div><div className="rounded-xl bg-muted/60 p-4"><p className="text-xs font-bold text-muted-foreground">Unassigned</p><p className="mt-2 font-mono-ui text-2xl font-bold">{incidents.filter((i) => !i.assignedTeam).length}</p><p className="mt-1 text-[11px] text-muted-foreground">need a match</p></div><div className="rounded-xl bg-muted/60 p-4"><p className="text-xs font-bold text-muted-foreground">On call</p><p className="mt-2 font-mono-ui text-2xl font-bold">01</p><p className="mt-1 text-[11px] text-muted-foreground">rapid response team</p></div></div></section></div>; }
function EmptyState({ title, text }: { title: string; text: string }) { return <div data-testid="empty-state" className="flex flex-col items-center py-14 text-center"><div className="flex size-12 items-center justify-center rounded-2xl bg-muted"><Filter size={20} className="text-muted-foreground" /></div><h3 className="mt-4 font-bold">{title}</h3><p className="mt-1 text-sm text-muted-foreground">{text}</p></div>; }

export default App;